"""The generated BYOC credentials: files/byoc_credentials.py and tasks/credentials.yml.

The name and password of this Pulsar's RabbitMQ account are generated when the component
parameters leave them empty, kept root-only on the storage volume (<storage>/byoc.json) and
reused on every rerun; a given parameter value wins over the stored one.
"""

import importlib.util
import io
import json
import os
import re
import runpy
import stat
import subprocess
import sys

import pytest

from tests.byoc_contract import validate
from tests.helpers import (
    PASSWORD,
    REPO,
    condition,
    load_yaml,
    play,
    resolve,
    resolve_text,
    task_named,
    tasks,
)
from tests.test_parameters import INVALID_NAMES, INVALID_PASSWORDS, VALID_NAMES, VALID_PASSWORDS

SCRIPT = REPO / "files" / "byoc_credentials.py"
SPEC = importlib.util.spec_from_file_location("byoc_credentials", SCRIPT)
byoc_credentials = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(byoc_credentials)

NAME_RE = re.compile(r"src[0-9a-f]{8}")
PASSWORD_RE = re.compile(r"[A-Za-z0-9]{24}")


def run(store, name="", password="", no_write=False):
    """Run the script as the task does: the given values on stdin, the result on stdout."""
    argv = [str(store)] + (["--no-write"] if no_write else [])
    stdin = io.StringIO(json.dumps({"name": name, "password": password}))
    stdout, stderr = io.StringIO(), io.StringIO()
    code = byoc_credentials.main(argv, stdin=stdin, stdout=stdout, stderr=stderr)
    return code, stdout.getvalue(), stderr.getvalue()


def result(store, **given):
    code, out, err = run(store, **given)
    assert code == 0, err
    assert err == ""
    return json.loads(out)


def stored(store):
    return json.loads(store.read_text())


def write_store(store, content):
    """A store as the script leaves it: readable by its owner only."""
    store.write_text(content)
    store.chmod(0o600)


@pytest.fixture
def store(tmp_path):
    return tmp_path / "byoc.json"


# Generation


def test_credentials_are_generated_and_stored(store):
    creds = result(store)

    assert NAME_RE.fullmatch(creds["name"]), creds["name"]
    assert PASSWORD_RE.fullmatch(creds["password"])
    assert creds["changed"] is True
    assert stored(store) == {"name": creds["name"], "password": creds["password"]}
    assert stat.S_IMODE(store.stat().st_mode) == 0o600
    assert sorted(path.name for path in store.parent.iterdir()) == ["byoc.json"]  # no temp file


def test_generated_credentials_pass_byoc_syncs_rules():
    for _ in range(50):
        name, password = byoc_credentials.generate_name(), byoc_credentials.generate_password()
        assert validate.is_valid_name(name), name
        assert validate._password(password, {}) == password


# The helper has its own copy of byoc-sync's rules (it runs with the system Python).


@pytest.mark.parametrize("name", VALID_NAMES + INVALID_NAMES)
def test_helper_name_rule_is_byoc_syncs(name):
    assert byoc_credentials.is_valid_name(name) == validate.is_valid_name(name)


@pytest.mark.parametrize("password", VALID_PASSWORDS + INVALID_PASSWORDS)
def test_helper_password_rule_is_byoc_syncs(password):
    assert byoc_credentials.is_valid_password(password) == (
        validate._password(password, {}) is not None
    )


def test_generated_credentials_are_random():
    assert len({byoc_credentials.generate_name() for _ in range(20)}) == 20
    assert len({byoc_credentials.generate_password() for _ in range(20)}) == 20


def test_a_rerun_reuses_the_stored_credentials(store):
    first = result(store)
    before = store.stat()

    second = result(store)

    assert second == {**first, "changed": False}
    assert store.stat().st_mtime_ns == before.st_mtime_ns


# Given values win


def test_a_given_name_replaces_the_stored_one_and_keeps_the_password(store):
    first = result(store)

    second = result(store, name=" alice01 ")

    assert second == {"name": "alice01", "password": first["password"], "changed": True}
    assert stored(store) == {"name": "alice01", "password": first["password"]}


def test_a_given_password_replaces_the_stored_one_and_keeps_the_name(store):
    first = result(store)

    second = result(store, password=PASSWORD)

    assert second == {"name": first["name"], "password": PASSWORD, "changed": True}
    assert stored(store)["password"] == PASSWORD


def test_given_credentials_are_stored_on_the_first_run(store):
    creds = result(store, name="alice01", password=PASSWORD)

    assert creds == {"name": "alice01", "password": PASSWORD, "changed": True}
    assert stored(store) == {"name": "alice01", "password": PASSWORD}
    # Unchanged when given again, and kept when no longer given.
    assert result(store, name="alice01", password=PASSWORD)["changed"] is False
    assert result(store) == {"name": "alice01", "password": PASSWORD, "changed": False}


@pytest.mark.parametrize(
    ("given", "parameter"),
    [({"name": "hpc_byoc"}, "pulsar_amqp_name"), ({"password": "short"}, "pulsar_amqp_password")],
)
def test_an_invalid_given_value_is_refused_and_nothing_is_stored(store, given, parameter):
    error = failure(store, **given)

    assert parameter in error
    assert "byoc-sync" in error
    assert "hpc_byoc" not in error
    assert "short" not in error
    assert not store.exists()


# Check mode


def test_no_write_leaves_the_store_alone(store):
    creds = result(store, no_write=True)

    assert NAME_RE.fullmatch(creds["name"])
    assert creds["changed"] is True
    assert not store.exists()
    assert list(store.parent.iterdir()) == []


def test_no_write_reports_a_change_without_making_it(store):
    first = result(store)

    second = result(store, name="alice01", no_write=True)

    assert second == {"name": "alice01", "password": first["password"], "changed": True}
    assert stored(store)["name"] == first["name"]


# A store that cannot be trusted is refused, without echoing anything in it.


def failure(store, **given):
    code, out, err = run(store, **given)
    assert code == 1
    assert out == ""
    assert PASSWORD not in err
    return err


@pytest.mark.parametrize(
    "content",
    [
        "not json",
        "[]",
        '{"name": "srcdeadbeef"}',
        f'{{"name": 1, "password": "{PASSWORD}"}}',
        f'{{"name": "srcdeadbeef", "password": "{PASSWORD}", "extra": 1}}',
        "",
    ],
    ids=["text", "list", "missing-key", "not-a-string", "extra-key", "empty"],
)
def test_a_corrupt_store_is_refused(store, content):
    write_store(store, content)

    error = failure(store)

    assert "not the credentials file" in error
    assert PASSWORD not in error
    assert store.read_text() == content


@pytest.mark.parametrize(
    ("name", "password"),
    [
        ("hpc_byoc", PASSWORD),
        ("HPC", PASSWORD),
        ("srcdeadbeef", "short"),
        ("srcdeadbeef", "a b" * 5),
    ],
)
def test_invalid_stored_credentials_are_refused_without_echoing_them(store, name, password):
    write_store(store, json.dumps({"name": name, "password": password}))

    error = failure(store)

    assert "byoc-sync" in error
    assert name not in error
    assert password not in error


def test_a_link_in_place_of_the_store_is_refused(store, tmp_path):
    target = tmp_path / "elsewhere.json"
    target.write_text(json.dumps({"name": "srcdeadbeef", "password": PASSWORD}))
    store.symlink_to(target)

    assert "regular file" in failure(store)


def test_a_store_readable_by_others_is_refused(store):
    store.write_text(json.dumps({"name": "srcdeadbeef", "password": PASSWORD}))
    store.chmod(0o644)

    assert "0600" in failure(store)


def test_an_unreadable_store_is_an_error_not_a_traceback(store, monkeypatch):
    write_store(store, json.dumps({"name": "srcdeadbeef", "password": PASSWORD}))
    real_open = open

    def failing_open(path, *args, **kwargs):
        if str(path) == str(store):
            raise OSError(5, "Input/output error")
        return real_open(path, *args, **kwargs)

    monkeypatch.setattr("builtins.open", failing_open)

    error = failure(store)

    assert "cannot read" in error
    assert str(store) in error
    assert "Input/output error" in error


def test_a_store_of_another_owner_is_refused(store, monkeypatch):
    write_store(store, json.dumps({"name": "srcdeadbeef", "password": PASSWORD}))
    monkeypatch.setattr(os, "geteuid", lambda: os.getuid() + 1)

    assert "owned by" in failure(store)


def test_a_missing_storage_directory_is_an_error_not_a_traceback(tmp_path):
    store = tmp_path / "missing" / "byoc.json"

    error = failure(store, password=PASSWORD)

    assert "cannot write" in error
    assert PASSWORD not in error


def test_a_failed_write_leaves_no_temporary_file(store, monkeypatch):
    # The store is replaced atomically: a failure leaves the old one, and nothing else.
    write_store(store, json.dumps({"name": "srcdeadbeef", "password": PASSWORD}))

    def refuse(source, target):
        raise OSError(28, "No space left on device")

    monkeypatch.setattr(os, "replace", refuse)

    error = failure(store, name="alice01")

    assert "cannot write" in error
    assert "No space left" in error
    assert PASSWORD not in error
    assert stored(store)["name"] == "srcdeadbeef"
    assert sorted(path.name for path in store.parent.iterdir()) == ["byoc.json"]


@pytest.mark.parametrize("text", ["", "[]", '{"name": "x"}', '{"name": null, "password": ""}'])
def test_bad_input_is_an_error(store, text):
    stderr = io.StringIO()
    code = byoc_credentials.main(
        [str(store)], stdin=io.StringIO(text), stdout=io.StringIO(), stderr=stderr
    )
    assert code == 1
    assert "stdin" in stderr.getvalue()
    assert not store.exists()


# As the task runs it


def test_script_runs_isolated_with_the_values_on_stdin(store):
    # -I: nothing from the environment or the current directory is imported.
    process = subprocess.run(  # noqa: S603 - fixed argv
        [sys.executable, "-I", str(SCRIPT), str(store)],
        input=json.dumps({"name": "", "password": PASSWORD}),
        capture_output=True,
        text=True,
        check=False,
    )

    assert process.returncode == 0, process.stderr
    creds = json.loads(process.stdout)
    assert NAME_RE.fullmatch(creds["name"])
    assert creds["password"] == PASSWORD
    assert stored(store)["password"] == PASSWORD


def test_script_exits_with_the_status(store, monkeypatch, capsys):
    # As the task runs it: `python3 -I byoc_credentials.py STORE`, the values on stdin.
    monkeypatch.setattr(sys, "argv", [str(SCRIPT), str(store)])
    monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps({"name": "", "password": ""})))

    with pytest.raises(SystemExit) as exit_info:
        runpy.run_path(str(SCRIPT), run_name="__main__")

    assert exit_info.value.code == 0
    creds = json.loads(capsys.readouterr().out)
    assert NAME_RE.fullmatch(creds["name"])
    assert stored(store)["name"] == creds["name"]


def test_script_exit_status_on_a_refused_store(store):
    write_store(store, "not json")
    process = subprocess.run(  # noqa: S603 - fixed argv
        [sys.executable, "-I", str(SCRIPT), str(store)],
        input=json.dumps({"name": "", "password": ""}),
        capture_output=True,
        text=True,
        check=False,
    )

    assert process.returncode == 1
    assert process.stdout == ""
    assert "not the credentials file" in process.stderr


# tasks/credentials.yml

CREDENTIAL_TASKS = tasks("tasks/credentials.yml")
GENERATED = {"name": "srcdeadbeef", "password": "Abc123" * 4, "changed": True}


def test_credentials_come_after_the_storage_and_before_anything_else():
    names = [task["name"] for task in play()["pre_tasks"]]
    storage = names.index("Check and prepare the attached storage")
    credentials = names.index("Load or create this Pulsar's BYOC credentials")

    assert credentials == storage + 1
    assert play()["pre_tasks"][credentials]["ansible.builtin.include_tasks"] == (
        "tasks/credentials.yml"
    )


def test_store_and_script_locations():
    assert resolve("pulsar_byoc_store") == "/data/pulsar_storage/pulsar/byoc.json"
    assert resolve("pulsar_byoc_script") == "/usr/local/libexec/pulsar-src/byoc_credentials.py"
    assert (
        resolve("pulsar_byoc_script").rsplit("/", 1)[0]
        == (resolve("pulsar_storage_check_script").rsplit("/", 1)[0])
    )


def test_script_is_installed_root_only_before_it_runs():
    names = [task["name"] for task in CREDENTIAL_TASKS]
    install = task_named(CREDENTIAL_TASKS, "Install the BYOC credentials helper")
    module = install["ansible.builtin.copy"]

    assert names.index(install["name"]) < names.index("Load or create the BYOC name and password")
    assert module["src"] == "files/byoc_credentials.py"
    assert module["dest"] == "{{ pulsar_byoc_script }}"
    assert (module["owner"], module["group"], module["mode"]) == ("root", "root", "0755")
    # Check mode on a fresh workspace: the helper must be there to run with --no-write.
    assert install["check_mode"] is False
    directory = task_named(
        tasks("tasks/storage.yml"), "Create the root-owned directory of this component's scripts"
    )
    assert directory["check_mode"] is False


@pytest.mark.parametrize("check_mode", [False, True])
def test_task_runs_the_script_with_the_parameters_on_stdin(check_mode):
    task = task_named(CREDENTIAL_TASKS, "Load or create the BYOC name and password")
    command = task["ansible.builtin.command"]
    variables = {
        "ansible_check_mode": check_mode,
        "pulsar_amqp_name": "",
        "pulsar_amqp_password": "",
    }

    argv = resolve_text(command["argv"], **variables)
    assert argv == [
        "/usr/bin/python3",
        "-I",
        "/usr/local/libexec/pulsar-src/byoc_credentials.py",
        "/data/pulsar_storage/pulsar/byoc.json",
        *(["--no-write"] if check_mode else []),
    ]
    assert json.loads(resolve_text(command["stdin"], **variables)) == {"name": "", "password": ""}
    assert json.loads(resolve_text(command["stdin"], pulsar_amqp_name="x")) == {
        "name": "x",
        "password": PASSWORD,
    }
    # A number from a YAML file (not SRC's strings) still reaches the helper as a string.
    assert json.loads(resolve_text(command["stdin"], pulsar_amqp_password=1234567890)) == {
        "name": "hpc",
        "password": "1234567890",
    }
    # The password passes through this task: nothing of it is logged, also when it fails.
    assert task["no_log"] is True
    assert task["check_mode"] is False
    assert task["failed_when"] is False
    assert task["register"] == "_pulsar_byoc"


def test_task_reports_a_change_from_the_script():
    task = task_named(CREDENTIAL_TASKS, "Load or create the BYOC name and password")
    for changed in (True, False):
        stdout = json.dumps({**GENERATED, "changed": changed})
        assert condition(task["changed_when"], _pulsar_byoc={"rc": 0, "stdout": stdout}) is changed
    # A failed run (no JSON) is not a change either; the next task reports it.
    assert condition(task["changed_when"], _pulsar_byoc={"rc": 1, "stdout": ""}) is False


def test_a_failed_script_fails_the_play_with_its_message():
    task = task_named(
        CREDENTIAL_TASKS, "Fail when the BYOC credentials cannot be loaded or created"
    )
    names = [t["name"] for t in CREDENTIAL_TASKS]

    assert names.index(task["name"]) == names.index("Load or create the BYOC name and password") + 1
    assert condition(task["when"], _pulsar_byoc={"rc": 1}) is True
    assert condition(task["when"], _pulsar_byoc={"rc": 0}) is False
    message = resolve_text(
        task["ansible.builtin.fail"]["msg"],
        _pulsar_byoc={"rc": 1, "stdout": "", "stderr": "/data/x/byoc.json is not the file\n"},
    )
    assert "/data/x/byoc.json is not the file" in message
    assert task.get("no_log") is not True


def test_settings_are_rebuilt_from_the_resolved_credentials():
    task = task_named(CREDENTIAL_TASKS, "Derive the connection settings from the credentials")
    expression = task["ansible.builtin.set_fact"]["_pulsar_amqp"]

    amqp = resolve_text(
        expression,
        **task["vars"],
        pulsar_amqp_name="",
        pulsar_amqp_password="",
        _pulsar_byoc={"rc": 0, "stdout": json.dumps(GENERATED)},
    )

    assert amqp["name"] == "srcdeadbeef"
    assert amqp["mq_user"] == "galaxy_srcdeadbeef_byoc"
    assert amqp["vhost"] == "/pulsar/galaxy_srcdeadbeef_byoc"
    assert amqp["url"] == (
        f"pyamqp://galaxy_srcdeadbeef_byoc:{GENERATED['password']}@mq.example.org:5671"
        "//pulsar/galaxy_srcdeadbeef_byoc"
    )
    assert amqp["storage_path"] == "/data/pulsar_storage/pulsar"
    assert task["no_log"] is True


def test_resolved_credentials_are_validated_again():
    task = task_named(CREDENTIAL_TASKS, "Validate the resolved credentials")
    check = task["ansible.builtin.assert"]
    valid = resolve("_pulsar_amqp")
    invalid = resolve("_pulsar_amqp", pulsar_amqp_name="hpc_byoc", pulsar_amqp_password="x" * 9)

    assert condition(check["that"], _pulsar_amqp=valid) is True
    assert condition(check["that"], _pulsar_amqp=invalid) is False
    message = resolve_text(check["fail_msg"], _pulsar_amqp=invalid)
    assert "pulsar_amqp_name" in message
    assert "pulsar_amqp_password" in message
    assert "x" * 9 not in message
    assert task.get("no_log") is not True  # the message must be visible
    names = [t["name"] for t in CREDENTIAL_TASKS]
    assert names.index(task["name"]) == len(names) - 1


def test_parameters_default_to_generated_credentials():
    parameters = load_yaml("parameters.yml")
    group_vars = load_yaml("group_vars/all.yml")

    assert parameters["pulsar_amqp_name"] == parameters["pulsar_amqp_password"] == ""
    assert group_vars["pulsar_amqp_name"] == group_vars["pulsar_amqp_password"] == ""
